"use client";

import { useState, useEffect } from "react";
import Link from "next/link";
import { usePathname } from "next/navigation";
import { motion, AnimatePresence } from "framer-motion";
import {
  Menu,
  X,
  ChevronDown,
  ArrowRight,
  Calendar,
  Clock,
  Globe,
  Zap,
} from "lucide-react";
import { projects } from "@/data/projects";
import { cn } from "@/lib/utils";

/* ---------------- NAV LINKS ---------------- */

const navLinks = [
  { name: "Product", href: "/products", hasMega: true },
  { name: "Services", href: "/services", hasMega: true },
  { name: "Blogs", href: "/blogs", hasMega: true },
  { name: "About", href: "/about", hasMega: true },
  { name: "Contact", href: "/contact", hasMega: false },
];

/* ---------------- MEGA MENU CONTENT ---------------- */

const megaMenuContent: Record<string, any> = {
  Product: [
    {
      title: "Commercial Platforms",
      items: projects
        .filter((p) => p.category === "Web Development")
        .map((p) => ({
          name: p.title,
          href: `/projects/${p.slug}`,
        })),
    },
    {
      title: "Full Stack Ecosystems",
      items: projects
        .filter((p) =>
          ["Full Stack", "EdTech"].includes(p.category)
        )
        .map((p) => ({
          name: p.title,
          href: `/projects/${p.slug}`,
        })),
    },
  ],

  Services: [
    {
      title: "Strategy & Engineering",
      items: [
        { name: "UI/UX Architecture", href: "/solutions/ui-ux-architecture" },
        { name: "Product Strategy", href: "/solutions/product-strategy" },
        { name: "Web Applications", href: "/solutions/web-apps" },
        { name: "Cloud Migration", href: "/solutions/cloud-ops" },
      ],
    },
  ],

  Blogs: [
    {
      title: "Tech & Insights",
      items: [
        { name: "Tutorials", href: "/blogs/tutorials" },
        { name: "Tech Trends", href: "/blogs/trends" },
        { name: "Case Studies", href: "/projects" },
      ],
    },
  ],

  About: [
    {
      title: "Company",
      items: [
        { name: "Mission", href: "/about" },
        { name: "Careers", href: "/careers" },
        { name: "Privacy Policy", href: "/privacy-policy" },
      ],
    },
  ],
};

/* ---------------- COMPONENT ---------------- */

export default function Navbar() {
  const [isOpen, setIsOpen] = useState(false);
  const [activeMega, setActiveMega] = useState<string | null>(null);
  const [scrolled, setScrolled] = useState(false);
  const [currentTime, setCurrentTime] = useState(new Date());

  const pathname = usePathname();

  /* ---------------- EFFECTS ---------------- */

  useEffect(() => {
    const timer = setInterval(() => {
      setCurrentTime(new Date());
    }, 1000);

    const handleScroll = () => {
      setScrolled(window.scrollY > 10);
    };

    window.addEventListener("scroll", handleScroll);

    document.body.style.overflow = isOpen ? "hidden" : "unset";

    return () => {
      clearInterval(timer);
      window.removeEventListener("scroll", handleScroll);
      document.body.style.overflow = "unset";
    };
  }, [isOpen]);

  const formatTime = (date: Date) =>
    date.toLocaleTimeString("en-IN", {
      hour: "2-digit",
      minute: "2-digit",
      hour12: true,
    });

  const formatDate = (date: Date) =>
    date.toLocaleDateString("en-IN", {
      day: "2-digit",
      month: "short",
      year: "numeric",
    });

  /* ---------------- JSX ---------------- */

  return (
    <motion.nav
      initial={{ y: -80 }}
      animate={{ y: 0 }}
      className={cn(
        "fixed top-0 left-0 right-0 z-[100] transition-all duration-300",
        scrolled
          ? "bg-background/80 backdrop-blur-2xl shadow-lg border-b border-border"
          : "bg-transparent"
      )}
    >
      {/* ---------- TOP BAR ---------- */}
      <div className="hidden lg:block border-b border-border/50 py-2 px-6 lg:px-10 text-sm text-muted-foreground">
        <div className="max-w-7xl mx-auto flex justify-between items-center">
          <div className="flex gap-6 items-center">
            <div className="flex items-center gap-2">
              <Calendar className="w-4 h-4 text-primary" />
              {formatDate(currentTime)}
            </div>
            <div className="flex items-center gap-2">
              <Clock className="w-4 h-4 text-primary" />
              {formatTime(currentTime)}
            </div>
          </div>

          <div className="flex items-center gap-6">
            <div className="flex items-center gap-2">
              <Globe className="w-4 h-4" /> EN
            </div>
            <Link href="/contact" className="text-primary font-medium">
              Support
            </Link>
          </div>
        </div>
      </div>

      {/* ---------- MAIN BAR ---------- */}
      <div className="px-4 sm:px-6 lg:px-10 py-4">
        <div className="max-w-7xl mx-auto flex justify-between items-center">
          {/* Logo */}
          <Link href="/" className="flex items-center gap-3">
            <div className="w-8 h-8 sm:w-10 sm:h-10 bg-primary rounded-xl flex items-center justify-center text-white font-bold">
              WK
            </div>
            <span className="text-lg sm:text-xl font-bold tracking-tight">
              WEBKARO<span className="text-primary">.</span>
            </span>
          </Link>

          {/* Desktop Nav */}
          <div className="hidden lg:flex items-center gap-8">
            {navLinks.map((link) => (
              <div
                key={link.name}
                className="relative"
                onMouseEnter={() =>
                  link.hasMega && setActiveMega(link.name)
                }
                onMouseLeave={() => setActiveMega(null)}
              >
                <Link
                  href={link.href}
                  className={cn(
                    "text-sm font-medium flex items-center gap-1 transition-colors",
                    pathname === link.href || activeMega === link.name
                      ? "text-primary"
                      : "text-muted-foreground hover:text-foreground"
                  )}
                >
                  {link.name}
                  {link.hasMega && (
                    <ChevronDown
                      className={cn(
                        "w-4 h-4 transition-transform",
                        activeMega === link.name && "rotate-180"
                      )}
                    />
                  )}
                </Link>

                {/* Mega Menu */}
                <AnimatePresence>
                  {activeMega === link.name && link.hasMega && (
                    <motion.div
                      initial={{ opacity: 0, y: 20 }}
                      animate={{ opacity: 1, y: 0 }}
                      exit={{ opacity: 0, y: 20 }}
                      className="absolute left-0 mt-6 bg-background border shadow-xl rounded-2xl p-8 w-[600px]"
                    >
                      {megaMenuContent[link.name]?.map((cat: any) => (
                        <div key={cat.title} className="mb-6">
                          <p className="text-xs uppercase text-muted-foreground mb-3">
                            {cat.title}
                          </p>
                          <div className="space-y-2">
                            {cat.items.map((item: any) => (
                              <Link
                                key={item.name}
                                href={item.href}
                                className="block text-sm hover:text-primary"
                              >
                                {item.name}
                              </Link>
                            ))}
                          </div>
                        </div>
                      ))}
                    </motion.div>
                  )}
                </AnimatePresence>
              </div>
            ))}
          </div>

          {/* CTA Desktop */}
          <div className="hidden lg:flex">
            <Link
              href="/contact"
              className="px-6 py-2 rounded-xl bg-primary text-white text-sm font-semibold flex items-center gap-2 hover:opacity-90 transition"
            >
              Start Project <ArrowRight className="w-4 h-4" />
            </Link>
          </div>

          {/* Mobile Menu Button */}
          <button
            onClick={() => setIsOpen(!isOpen)}
            className="lg:hidden"
          >
            {isOpen ? <X size={28} /> : <Menu size={28} />}
          </button>
        </div>
      </div>

      {/* ---------- MOBILE DRAWER ---------- */}
      <AnimatePresence>
        {isOpen && (
          <>
            <motion.div
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              exit={{ opacity: 0 }}
              onClick={() => setIsOpen(false)}
              className="fixed inset-0 bg-black/40 z-40"
            />

            <motion.div
              initial={{ x: "100%" }}
              animate={{ x: 0 }}
              exit={{ x: "100%" }}
              className="fixed top-0 right-0 bottom-0 w-full max-w-md bg-background border-l z-50 p-6 overflow-y-auto"
            >
              <button
                onClick={() => setIsOpen(false)}
                className="mb-8"
              >
                <X size={30} />
              </button>

              <div className="space-y-6">
                {navLinks.map((link) => (
                  <div key={link.name}>
                    <button
                      onClick={() =>
                        setActiveMega(
                          activeMega === link.name
                            ? null
                            : link.name
                        )
                      }
                      className="w-full flex justify-between items-center text-xl font-semibold"
                    >
                      {link.name}
                      {link.hasMega && (
                        <ChevronDown
                          className={`w-5 h-5 transition-transform ${
                            activeMega === link.name
                              ? "rotate-180"
                              : ""
                          }`}
                        />
                      )}
                    </button>

                    {activeMega === link.name &&
                      megaMenuContent[link.name] && (
                        <div className="mt-4 pl-4 space-y-4">
                          {megaMenuContent[
                            link.name
                          ].map((cat: any) => (
                            <div key={cat.title}>
                              <p className="text-xs uppercase text-muted-foreground mb-2">
                                {cat.title}
                              </p>
                              {cat.items.map((item: any) => (
                                <Link
                                  key={item.name}
                                  href={item.href}
                                  onClick={() => setIsOpen(false)}
                                  className="block text-sm mb-2 hover:text-primary"
                                >
                                  {item.name}
                                </Link>
                              ))}
                            </div>
                          ))}
                        </div>
                      )}
                  </div>
                ))}
              </div>

              <div className="mt-10">
                <Link
                  href="/contact"
                  onClick={() => setIsOpen(false)}
                  className="w-full py-4 rounded-xl bg-primary text-white text-center font-semibold block"
                >
                  Start Project
                </Link>
              </div>
            </motion.div>
          </>
        )}
      </AnimatePresence>
    </motion.nav>
  );
}
